# Generated: the window Kevin's mods share, taken from Hunter Change's plain window, under It Follows'
# names. Its comments may speak of other mods. Never edited by hand: docs/RUN/outils/menu_window.py
# writes this file.
# Generated by sync_menu_ui; edit canonical sources.
"""Anton and Barlow Condensed as Unreal fonts, built at runtime from the copied TTF files, with Noto Sans as the
fallback for the Chinese and Japanese characters they lack in the mods offering those languages.

A font with a runtime cache reads its faces from file names, the path Slate's own core fonts take in a packaged
game. Rebuilt at each opening: the text widgets using a font are what keep it alive, nothing else holds it.

A window in Japanese draws from Noto Sans JP, any other from Noto Sans SC: the kanji Japanese shares with Chinese take
Chinese shapes in the Chinese faces (2026-10-21). One fallback per font, chosen when the window is built: a language
change between the two draws the window again (panel_language_choice.py).
"""

import unrealsdk as sdk

from . import panel_assets as assets, panel_theme as t, panel_widgets as w
from .panel_preferences import LANGUAGES

FACES = {
    "title": (("Regular", "Anton-Regular.ttf"),),
    "body": (("Medium", "BarlowCondensed-Medium.ttf"), ("SemiBold", "BarlowCondensed-SemiBold.ttf"),
             ("ExtraBold", "BarlowCondensed-ExtraBold.ttf")),
}
# The mockup's CSS weights, mapped to the Barlow files shipped; Anton has a single weight.
WEIGHTS = {t.WEIGHT_REGULAR: "Medium", t.WEIGHT_MEDIUM: "SemiBold", t.WEIGHT_BOLD: "ExtraBold"}
# Slate takes from the fallback the face whose boldness is closest to the requested one's.
FALLBACKS = {
    "ZH": {"title": (("Black", "NotoSansSC-Black.ttf"),),
           "body": (("Medium", "NotoSansSC-Medium.ttf"), ("ExtraBold", "NotoSansSC-ExtraBold.ttf"))},
    "JA": {"title": (("Black", "NotoSansJP-Black.ttf"),),
           "body": (("Medium", "NotoSansJP-Medium.ttf"), ("ExtraBold", "NotoSansJP-ExtraBold.ttf"))},
}
_script = "ZH"  # the next build's fallback, set by use() as panel_theme.use sets the colours


def script(language):
    """Which fallback faces a window in this language draws from."""
    return "JA" if language == "JA" else "ZH"


def use(language):
    global _script
    _script = script(language)


def build(outer):
    """Family -> font object. A family whose files or font class are unavailable is left out: engine font."""
    fonts = {}
    for family, faces in FACES.items():
        files = _files(faces)
        if files is None:
            continue
        made = []
        w.cosmetic(f"font:{family}", lambda files=files, made=made: made.append(_font(outer, files)))
        if made:
            fonts[family] = made[0]
            fallback = _fallback_files(family)
            if fallback is not None:
                w.cosmetic(f"font_fallback:{family}", lambda font=made[0], files=fallback: _fallback(font, files))
    return fonts


def _fallback_files(family):
    """The faces of the window's script, those of Chinese when they cannot be read (kana and kanji still drawn), or
    None in a mod offering neither."""
    for code in dict.fromkeys((_script, "ZH")):
        files = _files(FALLBACKS[code][family]) if code in LANGUAGES else None
        if files is not None:
            return files
    return None


def _files(faces):
    files = tuple((name, assets.path(file)) for name, file in faces)
    return None if any(path is None for _, path in files) else files


def _entries(files):
    return [sdk.make_struct("TypefaceEntry", Name=name, Font=sdk.make_struct(
        "FontData", FontFilename=path, Hinting=w.enum("EFontHinting", "Default"),
        LoadingPolicy=w.enum("EFontLoadingPolicy", "LazyLoad"), SubFaceIndex=0))
        for name, path in files]


def _font(outer, files):
    font = sdk.construct_object("Font", outer)
    font.FontCacheType = w.enum("EFontCacheType", "Runtime")
    composite = font.CompositeFont
    composite.DefaultTypeface.Fonts = _entries(files)
    # Written back whole, so the faces land whether the SDK handed out the struct or a copy of it.
    font.CompositeFont = composite
    return font


def _fallback(font, files):
    composite = font.CompositeFont
    composite.FallbackTypeface.Typeface.Fonts = _entries(files)
    composite.FallbackTypeface.ScalingFactor = 1.0
    font.CompositeFont = composite


def face(family, weight):
    return "Regular" if family == "title" else WEIGHTS[weight]
